fn main () { println ! ("{:?}" , backspace_compare ("ab#c" , "ad#c")) ; } fn backspace_compare (u : & str , v : & str) -> bool { let mut i = u . chars () . into_iter () . peekable () ; let mut j = v . chars () . into_iter () . peekable () ; let mut a_in_bs = false ; let mut b_in_bs = false ; loop { let a = if ! a_in_bs && let Some (a) = i . next () { a } else { break } ; let b = if ! b_in_bs && let Some (a) = j . next () { a } else { break } ; } return true ; }